package profile
type Profile struct{Version string `json:"version"`;Job string `json:"job"`;Target Target `json:"target"`;StartedAt string `json:"started_at"`;FinishedAt string `json:"finished_at"`;DurationMS int64 `json:"duration_ms"`;TotalBytes int64 `json:"total_bytes"`;TotalRows int64 `json:"total_rows"`;ThroughputMB float64 `json:"throughput_mb_s"`;Tables []TableProfile `json:"tables"`}
type Target struct{Database string `json:"database"`;Version string `json:"version"`;Engine string `json:"engine"`;Charset string `json:"charset"`}
type TableProfile struct{File string `json:"file"`;Table string `json:"table"`;SizeBytes int64 `json:"size_bytes"`;Rows int64 `json:"rows"`;DurationMS int64 `json:"duration_ms"`;Columns map[string]*ColumnProfile `json:"columns"`}
type ColumnProfile struct{Present int64 `json:"present"`;Empty int64 `json:"empty"`;MaxChars int `json:"max_chars"`;MaxBytes int `json:"max_bytes"`;MinChars int `json:"min_chars"`;IntegerMatches int64 `json:"integer_matches"`;DecimalMatches int64 `json:"decimal_matches"`;DateMatches int64 `json:"date_matches"`;DateTimeMatches int64 `json:"datetime_matches"`;LeadingZero bool `json:"leading_zero"`;MaxPrecision int `json:"max_precision"`;MaxScale int `json:"max_scale"`;MaxFraction int `json:"max_fraction_seconds"`;Samples []string `json:"samples,omitempty"`;Distinct map[string]bool `json:"-"`;DistinctValues []string `json:"distinct_values,omitempty"`;DistinctTruncated bool `json:"distinct_truncated"`}
